document.addEventListener("DOMContentLoaded",(function(){const e=document.querySelector(".card-container"),t=document.getElementById("ajax-filter-multi");t.addEventListener("change",(n=>{n.preventDefault();const o=new FormData(t);fetch(ajaxurl+"?action=ajaxfilter2",{method:"POST",headers:{"Content-Type":"application/json"},body:JSON.stringify(Object.fromEntries(o.entries()))}).then((e=>e.text())).then((t=>{t&&(e.innerHTML=t)})).catch((e=>{console.log(e)}))}))}));